urlset:
{% for path in static_pages %}
{{ site_url }}{{ path }}
{% endfor %}
{{ site_url }}/blog{% if updated %}{{ updated }}{% endif %}
{% for c in categories %}
{{ site_url }}/blog/category/{{ c.slug }}
{% endfor %}
{% for a in items %}
{{ site_url }}/blog/{{ a.slug }}{{ a.content_updated_at or a.published_at }}
{% endfor %}
